    var weekday = sessionWeekdayLabel(s.endedAt);
    var when = historyDayDateLabel(s.endedAt);
    var durTxt = (Number(s.durationSec) || 0) > 0 ? fmtDurShort(s.durationSec) : '—';
    var vol = fmtNum(sessionVolume(s));
