    if (!S.history.selectedSessionId) return;
    S.history.selectedSessionId = null;
    mountHistoryOverlay();
    var root = document.getElementById('historyOverlayRoot');
    var wrap = root && root.firstElementChild;
    if (wrap) requestAnimationFrame(function () { wrap.scrollTop = S.history.scrollY || 0; });
