$('#fileImport').onchange = async e => { let f = e.target.files[0]; if (!f) return; let j = JSON.parse(await f.text()); if (j.nome_scheda) { await Store.clear('cards'); await importPlan(j) } e.target.value = '' };

// ====== Sessioni incomplete: rilevamento + UI ======
function incompleteSessions() {
    return (S.sessions || []).filter(s => s.startedAt && !s.endedAt)
        .sort((a, b) => String(b.updatedAt || b.startedAt).localeCompare(String(a.updatedAt || a.startedAt)));
}
function fmtElapsed(sec) {
    sec = Math.max(0, Math.floor(sec));
    var h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60), s = sec % 60;
    return (h < 10 ? '0' : '') + h + ':' + (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
}
function sessionLabel(s) {
    var c = resolveSessionCard(s);

    var w = c && c.weeks.find(function (x) {
        return x.key === s.weekKey;
    });

    var d = w && w.days.find(function (x) {
        return x.key === s.dayKey;
    });

    return (w ? w.label : '?') + ' • ' + (d ? d.label + ' — ' + d.name : '?');
}
async function checkIncompleteSessions() {
    var list = incompleteSessions();
    if (!list.length) return;
    // se ce ne e gia una attiva non aprire modal
    if (S.active && S.active.startedAt && !S.active.endedAt) return;
    openResumeModal(list);
}
var __activeModal = null;
function closeModal() {
    if (__activeModal && typeof __activeModal.close === 'function') { __activeModal.close(); }
}
function mountModalDelegation(handle) {
    if (!handle || !handle.root) return;
    handle.root.addEventListener('click', function (e) {
        var btn = e.target.closest('[data-action]');
        if (!btn || btn.disabled) return;
        var action = btn.dataset.action;
        var id = btn.dataset.id || '';
        switch (action) {
            case 'resume-session':      resumeSession(id); break;
            case 'discard-session':     discardSession(id); break;
            case 'close-session-now':   closeSessionNow(id); break;
            case 'open-duration-modal': openDurationModal(id); break;
            case 'save-manual-duration': saveManualDuration(id); break;
            case 'close-modal':         closeModal(); break;
            case 'confirm-reset-ok':    closeModal(); resetAndLoad(); break;
        }
    });
}
function openResumeModal(list) {
    closeModal();
    var UI = window.UI;
    if (!UI || !UI.showBottomSheet || !UI.Button) return;
    var rows = list.map(function (s) {
        var elapsed = Math.floor((Date.now() - Date.parse(s.startedAt)) / 1000);
        var over4h = elapsed > 4 * 3600;
        var warn = over4h ? ' &middot; <span style="color:var(--color-error)">oltre 4h</span>' : '';
        var actionBtn = over4h
            ? UI.Button({ label: 'Chiudi a mano', variant: 'primary',   dataset: { action: 'open-duration-modal', id: s.id } })
            : UI.Button({ label: 'Chiudi ora',    variant: 'primary',   dataset: { action: 'close-session-now',   id: s.id } });
        return '<div class="modalRow" data-id="' + esc(s.id) + '">' +
            '<div>' +
                '<b>' + esc(sessionLabel(s)) + '</b>' +
                '<div class="meta">Inizio: ' + esc(new Date(s.startedAt).toLocaleString()) +
                ' &middot; Tempo trascorso: ' + fmtElapsed(elapsed) + warn + '</div>' +
            '</div>' +
            '<div class="row" style="flex-wrap:wrap; gap:var(--space-8)">' +
                UI.Button({ label: 'Riprendi', variant: 'secondary', dataset: { action: 'resume-session',  id: s.id } }) +
                UI.Button({ label: 'Scarta',   variant: 'danger',    dataset: { action: 'discard-session', id: s.id } }) +
                actionBtn +
            '</div>' +
        '</div>';
    }).join('');
    var footer = '<div class="row" style="justify-content:flex-end; margin-top:var(--space-8)">' +
        UI.Button({ label: 'Più tardi', variant: 'ghost', dataset: { action: 'close-modal' } }) +
        '</div>';
    var body = '<p class="muted" style="margin:0 0 var(--space-12)">Hai ' + list.length +
        ' sessione/i aperte. Cosa vuoi farci?</p>' + rows + footer;
    __activeModal = UI.showBottomSheet({
        title: 'Sessioni non chiuse',
        content: body,
        onClose: function () { __activeModal = null; }
    });
    mountModalDelegation(__activeModal);
}

async function resumeSession(id) {
    var s = S.sessions.find(function (x) {
        return x.id === id;
    });

    if (!s) return;

    var card = resolveSessionCard(s);
    if (card) {
        s.cardId = card.id;
    }

    closeModal();

    S.active = { ...s };
    S.active.endedAt = null;
    S.active.updatedAt = now();
    S.active.syncStatus = 'local';

    stopRestTimer(false);

    if (S.active.startedAt) {
        startSessionTimer();
    } else {
        stopSessionTimer();
    }

    S.tab = 'workout';

    await persistActive(true);
    await refresh();

    S.tab = 'workout';
    render();
    appToast('Sessione ripristinata', 'info');
}
async function discardSession(id) {
    var s = S.sessions.find(function (x) {
        return x.id === id;
    });

    if (!s) return;

    s.endedAt = now();
    s.durationSec = 0;
    s.completedSets = 0;
    s.totalVolume = 0;
    s.discarded = true;
    s.updatedAt = now();
    s.syncStatus = 'local';

    await Store.put('sessions', s);

    if (S.active && S.active.id === id) {
        S.active = null;
        stopRestTimer(false);
        stopSessionTimer();
    }

    await refresh();

    var others = incompleteSessions().filter(function (x) {
        return x.id !== id;
    });

    closeModal();
    appToast('Sessione eliminata', 'success');

    if (others.length) {
        openResumeModal(others);
    }
}
async function closeSessionNow(id) {
    var s = S.sessions.find(x => x.id === id);
    if (!s) return;
    await fillMissingFromPrevious(s);
    s.endedAt = now();
    s.durationSec = Math.round((Date.now() - Date.parse(s.startedAt)) / 1000);
    s.completedSets = (s.exerciseLogs || []).filter(x => x.done).length;
    s.totalVolume = (s.exerciseLogs || []).reduce((n, x) => n + (Number(x.kg) || 0) * repsNumber(x.reps), 0);
    s.updatedAt = now();
    s.syncStatus = 'local';
    await Store.put('sessions', s);
    await refresh();
    closeModal();
    var others = incompleteSessions();
    if (others.length) openResumeModal(others);
}

// ====== Modal durata manuale per > 4 ore ======
function openDurationModal(id) {
    closeModal();
    var UI = window.UI;
    var s = S.sessions.find(function (x) { return x.id === id; });
    if (!s || !UI || !UI.showDialog || !UI.Button) return;
    var body = '<p class="muted" style="margin:0 0 var(--space-12)">' + esc(sessionLabel(s)) + '</p>' +
        '<div class="row" style="gap:var(--space-8); align-items:center">' +
            '<label for="durH">Ore</label>' +
            '<input id="durH" inputmode="numeric" pattern="[0-9]*" type="number" min="0" max="6" value="1" style="max-width:80px">' +
            '<label for="durM">Minuti</label>' +
            '<input id="durM" inputmode="numeric" pattern="[0-9]*" type="number" min="0" max="59" value="0" style="max-width:80px">' +
        '</div>' +
        '<p class="muted" style="margin:var(--space-12) 0 0">Formato HH:MM. La sessione verrà chiusa con questa durata.</p>';
    var actions =
        UI.Button({ label: 'Annulla',         variant: 'ghost',   dataset: { action: 'close-modal' } }) +
        UI.Button({ label: 'Salva e chiudi',  variant: 'primary', dataset: { action: 'save-manual-duration', id: s.id } });
    __activeModal = UI.showDialog({
        title: 'Quanto è durato l\'allenamento?',
        body: ' ',
        actions: actions,
        onClose: function () { __activeModal = null; }
    });
    if (__activeModal && __activeModal.root) {
        var bodyEl = __activeModal.root.querySelector('.c-dialog__body');
        if (bodyEl) bodyEl.innerHTML = body;
    }
    mountModalDelegation(__activeModal);
}
async function saveManualDuration(id) {
    var s = S.sessions.find(x => x.id === id);
    if (!s) return;
    var h = Math.max(0, Number(document.getElementById('durH').value) || 0);
    var m = Math.max(0, Math.min(59, Number(document.getElementById('durM').value) || 0));
    var durationSec = h * 3600 + m * 60;
    await fillMissingFromPrevious(s);
    s.durationSec = durationSec;
    s.endedAt = new Date(Date.parse(s.startedAt) + durationSec * 1000).toISOString();
    s.completedSets = (s.exerciseLogs || []).filter(x => x.done).length;
    s.totalVolume = (s.exerciseLogs || []).reduce((n, x) => n + (Number(x.kg) || 0) * repsNumber(x.reps), 0);
    s.updatedAt = now();
    s.syncStatus = 'local';
    await Store.put('sessions', s);
    await refresh();
    closeModal();
    var others = incompleteSessions();
    if (others.length) openResumeModal(others);
}

// ====== Riempimento automatico dati mancanti dalla sessione precedente ======
function findPreviousCompleted(s) {
    var list = (S.sessions || []).filter(function (x) {
        return x.weekKey === s.weekKey &&
            x.dayKey === s.dayKey &&
            x.endedAt &&
            !x.discarded &&
            x.id !== s.id;
    }).sort(function (a, b) {
        return String(b.endedAt).localeCompare(String(a.endedAt));
    });

    return list[0] || null;
}
function findInLog(logs, blockId, exerciseId, setNo) {
    return (logs || []).find(l => l.blockId === blockId && l.exerciseId === exerciseId && l.setNo === setNo);
}

async function fillMissingFromPrevious(s) {
    var c = S.cards.find(function (x) {
        return x.id === s.cardId;
    });

    var w = c && c.weeks.find(function (x) {
        return x.key === s.weekKey;
    });

    var d = w && w.days.find(function (x) {
        return x.key === s.dayKey;
    });

    if (!d) return [];

    var prev = findPreviousCompleted(s);
    s.exerciseLogs = s.exerciseLogs || [];

    var missing = [];

    for (var bi = 0; bi < d.blocks.length; bi++) {
        var b = d.blocks[bi];
        var rounds = +b.rounds || 3;

        for (var ei = 0; ei < b.exerciseIds.length; ei++) {
            var ex = b.exerciseIds[ei];

            for (var setNo = 1; setNo <= rounds; setNo++) {
                var cur = findInLog(s.exerciseLogs, b.id, ex, setNo);

                if (cur && cur.kg) {
                    continue;
                }

                if (prev) {
                    var p = findInLog(prev.exerciseLogs, b.id, ex, setNo);

                    if (p) {
                        if (!cur) {
                            s.exerciseLogs.push({
                                blockId: b.id,
                                exerciseId: ex,
                                setNo: setNo,
                                kg: p.kg || 0,
                                reps: p.reps || '',
                                done: false,
                                updatedAt: now()
                            });
                        } else {
                            cur.kg = cur.kg || p.kg || 0;
                            cur.reps = cur.reps || p.reps || '';
                            cur.updatedAt = now();
                        }

                        continue;
                    }
                }

                missing.push({
                    blockId: b.id,
                    exerciseId: ex,
                    setNo: setNo,
                    blockIndex: bi
                });
            }
        }
    }

    return missing;
}

function exportAll() {
    let a = document.createElement('a');
    a.href = URL.createObjectURL(new Blob([
        JSON.stringify({ cards: S.cards, exercises: S.exercises, sessions: S.sessions }, null, 2)
    ], { type: 'application/json' }));
    a.download = 'fit-circuit-backup.json';
    a.click();
}

// ====== Sync GitHub ======
async function loadSyncConfig() {
    var cfg = await Store.get('settings', 'sync-config');
    if (cfg && cfg.value) S.sync.config = cfg.value;
    var meta = await Store.get('settings', 'sync-meta');
    if (meta && meta.value && meta.value.lastSyncAt) S.sync.lastSyncAt = meta.value.lastSyncAt;
}
async function saveSyncConfig() {
    var cfg = {
        owner: (document.getElementById('ghOwner').value || '').trim(),
        repo: (document.getElementById('ghRepo').value || '').trim(),
        path: (document.getElementById('ghPath').value || 'backup.json').trim(),
        branch: (document.getElementById('ghBranch').value || 'main').trim(),
        token: (document.getElementById('ghToken').value || '').trim()
    };
    S.sync.config = cfg;
    await Store.put('settings', { id: 'sync-config', value: cfg });
    render();
    syncToRemote({ manual: true });
}
async function clearSyncConfig() {
    if (!confirm('Rimuovere le credenziali GitHub salvate?')) return;
    S.sync.config = null;
    S.sync.status = 'idle';
    S.sync.lastError = null;
    await Store.del('settings', 'sync-config');
    render();
}
function renderSyncStatus() {
    var el = document.getElementById('syncStatus');
    if (!el) return;
    var st = S.sync.status || 'idle';
    var last = S.sync.lastSyncAt ? new Date(S.sync.lastSyncAt).toLocaleString() : 'mai';
    var on = navigator.onLine ? 'online' : 'offline';
    var err = S.sync.lastError ? ' · Errore: ' + S.sync.lastError : '';
    el.textContent = 'Stato: ' + st + ' · ' + on + ' · Ultimo sync: ' + last + err;
}
function scheduleSync() {
    if (!S.sync.config || !S.sync.config.token) return;
    clearTimeout(window.__syncT);
    window.__syncT = setTimeout(function () { syncToRemote(); }, 30000);
}
async function syncToRemote(opts) {
    opts = opts || {};
    var cfg = S.sync.config;
    if (!cfg || !cfg.token || !cfg.owner || !cfg.repo) {
        if (opts.manual) alert('Compila owner, repo e token, poi Salva.');
        return;
    }
    if (!navigator.onLine) {
        S.sync.status = 'offline (in attesa di rete)';
        renderSyncStatus();
        return;
    }
    if (S.sync.busy) { S.sync.pending = true; return; }
    S.sync.busy = true;
    S.sync.status = 'sincronizzazione...';
    S.sync.lastError = null;
    renderSyncStatus();
    try {
        var path = cfg.path || 'backup.json';
        var branch = cfg.branch || 'main';
        var base = 'https://api.github.com/repos/' + encodeURIComponent(cfg.owner) + '/' + encodeURIComponent(cfg.repo) + '/contents/' + encodeURI(path);
        var headers = {
            'Authorization': 'Bearer ' + cfg.token,
            'Accept': 'application/vnd.github+json',
            'X-GitHub-Api-Version': '2022-11-28'
        };
        var sha = null;
        var g = await fetch(base + '?ref=' + encodeURIComponent(branch), { headers: headers, cache: 'no-store' });
        if (g.ok) { var gj = await g.json(); sha = gj.sha; }
        else if (g.status !== 404) { throw new Error('GET ' + g.status); }
        var payload = { cards: S.cards, exercises: S.exercises, sessions: S.sessions, exportedAt: now() };
        var content = btoa(unescape(encodeURIComponent(JSON.stringify(payload))));
        var body = { message: 'sync ' + now(), content: content, branch: branch };
        if (sha) body.sha = sha;
        var p = await fetch(base, { method: 'PUT', headers: Object.assign({}, headers, { 'Content-Type': 'application/json' }), body: JSON.stringify(body) });
        if (!p.ok) {
            var t = await p.text().catch(function () { return ''; });
            throw new Error('PUT ' + p.status + ' ' + t.slice(0, 160));
        }
        S.sync.lastSyncAt = now();
        await Store.put('settings', { id: 'sync-meta', value: { lastSyncAt: S.sync.lastSyncAt } });
        S.sync.status = 'ok';
    } catch (e) {
        S.sync.status = 'errore';
        S.sync.lastError = String(e && e.message || e);
    }
    S.sync.busy = false;
    renderSyncStatus();
    if (S.sync.pending) { S.sync.pending = false; setTimeout(function () { syncToRemote(); }, 500); }
}
async function restoreFromRemote() {
    var cfg = S.sync.config;
    if (!cfg || !cfg.token || !cfg.owner || !cfg.repo) return alert('Configura prima le credenziali GitHub.');
    if (!navigator.onLine) return alert('Sei offline: impossibile ripristinare ora.');
    try {
        var path = cfg.path || 'backup.json';
        var branch = cfg.branch || 'main';
        var url = 'https://api.github.com/repos/' + encodeURIComponent(cfg.owner) + '/' + encodeURIComponent(cfg.repo) + '/contents/' + encodeURI(path) + '?ref=' + encodeURIComponent(branch);
        var r = await fetch(url, { headers: { 'Authorization': 'Bearer ' + cfg.token, 'Accept': 'application/vnd.github+json' }, cache: 'no-store' });
        if (r.status === 404) return alert('Nessun backup trovato nel repo.');
        if (!r.ok) return alert('Errore ripristino: HTTP ' + r.status);
        var j = await r.json();
        var raw = atob((j.content || '').replace(/\s/g, ''));
        var text = decodeURIComponent(escape(raw));
        var data = JSON.parse(text);
        if (!confirm('Ripristino sovrascriverà i dati locali (' + S.sessions.length + ' sessioni). Continuare?')) return;
        await Store.clear('cards');
        await Store.clear('exercises');
        await Store.clear('sessions');
        for (var i = 0; i < (data.cards || []).length; i++) await Store.put('cards', data.cards[i]);
        for (var i = 0; i < (data.exercises || []).length; i++) await Store.put('exercises', data.exercises[i]);
        for (var i = 0; i < (data.sessions || []).length; i++) await Store.put('sessions', data.sessions[i]);
        await refresh();
        alert('Ripristino completato: ' + (data.sessions || []).length + ' sessioni caricate.');
    } catch (e) {
        alert('Errore ripristino: ' + (e && e.message || e));
    }
}

// Autosave globale ad ogni interazione
['click', 'change', 'touchend', 'keyup'].forEach(ev => {
    document.addEventListener(ev, () => { if (S.active) persistActive(); }, true);
});
document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'hidden' && S.active) persistActive(true);
    // Sprint 4.5: non riaprire automaticamente il modale ad ogni cambio visibilità.
    // La Restore Banner in Home e l'empty state del tab Workout guidano l'utente.
});
window.addEventListener('beforeunload', () => { if (S.active) persistActive(true); });

// Bridge tema: la libreria UI (Shared/Theme.js) dispatcha 'ui:theme-set' con detail.name.
// L'app.js resta unica fonte per S.theme + localStorage + applyTheme().
document.addEventListener('ui:theme-set', function (e) {
    var name = e && e.detail && e.detail.name;
    if (name !== 'system' && name !== 'light' && name !== 'dark' && name !== 'amoled') return;
    S.theme = name;
    localStorage.theme = name;
    applyTheme();
});

if ('serviceWorker' in navigator) {
    navigator.serviceWorker.register('./sw.js').catch(function () { });
}
window.addEventListener('online', function () { renderSyncStatus(); syncToRemote(); });
window.addEventListener('offline', function () { renderSyncStatus(); });

(async () => {
    // T0.4 · Catalogo esercizi su DB separato (fit-catalog-v1). Fire-and-forget:
    // il picker esercizi (T1.6) leggera in memoria via catalogService; l'app boota
    // anche senza catalogo (picker mostrera stato vuoto in caso di errore).
    import('./services/catalogService.js')
        .then(function (m) { return m.initCatalog(); })
        .catch(function (err) { console.warn('catalog init failed:', err); });
    await Store.open();
    await loadSyncConfig();
    // Sprint 7: primo avvio → segna installedAt e (se GitHub è configurato) precompila nome utente.
    initFirstBootUser();
    mountViewDelegation();
    await refresh();
    if (!S.cards.length) { await importPlan(EMBEDDED_SCHEDA); }
    await migrateDedupExercises();
    // Sprint 4.5: pulizia bozze silenti (Draft senza log) più vecchie di 24h.
    var cleaned = autoCleanupOldDrafts();
    if (cleaned) await refresh();
    // Sprint 4.5: non aprire più il modale al boot. Restore Banner (Home) + workoutPending
    // guidano l'utente. Il modale resta accessibile via bottone "Gestisci →" in Profilo.
    if (S.sync.config && S.sync.config.token && S.sessions.length === 0 && navigator.onLine) {
        setTimeout(function () {
            if (confirm('Nessuna sessione locale ma è configurato il backup GitHub. Ripristinare dal remoto?')) restoreFromRemote();
        }, 300);
    }
})();
